  'assessment.reading.next_step.read_widely': 'Read widely',
  'assessment.reading.next_step.read_widely_body':
    'Aim for 15-20 minutes of reading daily across fiction and non-fiction at your reading level.',
  'assessment.reading.next_step.practise_comprehension': 'Practise comprehension',
  'assessment.reading.next_step.practise_comprehension_body':
    'Work through reading comprehension exercises, focusing on inference and evaluation questions.',
  'assessment.reading.next_step.build_vocab': 'Build vocabulary',
  'assessment.reading.next_step.build_vocab_body':
    'Learn new words in context. Keep a vocabulary journal and review unfamiliar words regularly.',
  'assessment.reading.retake': 'Retake Assessment',
