  'revision.grade_targets.skill.writer_methods': "Understanding of writer's methods",
  'revision.grade_targets.skill.developed_analysis': 'Thoughtful, developed analysis',
  'revision.grade_targets.skill.judicious_quotes': 'Judicious use of quotes',
