  'revision.common_errors.verification_badge': 'Verification standard',
  'revision.common_errors.verification_heading': 'Every flag is verified against a primary source',
  'revision.common_errors.verification_body':
    "Where a board specifies a particular edition or version, we cite that edition. Where a writer's biography is in dispute, we use the writer's own statements. Spot something we got wrong?",
  'revision.common_errors.tell_us': 'Tell us',
  'revision.common_errors.keep_going_heading': 'Keep going',
